 const g=i=>$("tx_"+i),bal=()=>{const F=buildFunds(S.finances,S.ledger);const c=(cl,l,v)=>`<div class="fund ${cl}${v<0?" neg":""}"><small>${l}</small><strong>${cash(v)}</strong></div>`;$("fdBal").innerHTML=c("op","OPERATING FUND",F.bal.operating)+c("sv","SAVINGS",F.bal.savings)+c("of","OFFERING (not yet given)",F.bal.offering);$("fdDue").textContent=`Set aside and not yet given to the Church: Tithes ${cash(F.due.tithes)} · Offering ${cash(F.due.offering)}`};
