 const filt=()=>{const q=g("q").value.trim().toLowerCase(),ty=g("ft").value,mo=g("fm").value;return S.ledger.map((x,i)=>[x,i]).filter(([x])=>(!ty||x.type===ty)&&(!mo||(x.date||"").slice(0,7)===mo)&&(!q||[x.donor,x.source,x.category,x.details,x.service,x.type,x.fund].join(" ").toLowerCase().includes(q))).sort((a,b)=>(b[0].date||"").localeCompare(a[0].date||""))};
