 g("csv2").onclick=()=>{const F=buildFunds(S.finances,S.ledger),rows=[["Date","Fund","Details","Amount (+/-)","Running balance"]];F.M.forEach(m=>rows.push([m.date||"",fundName(m.fund),m.details||"",r2(m.delta),r2(m.bal)]));csvDl("fst-fund-movements-"+today()+".csv",rows)};
